    let answer='已围绕「'+goal+'」完成本次工作。';
    if(findings.length)answer+='\n\n检索到 '+findings.length+' 条资料：\n'+findings.slice(0,5).map((item,i)=>(i+1)+'. '+(item.title||item.name||JSON.stringify(item))+((item.summary||item.text)?'\n   '+(item.summary||item.text):'')).join('\n');
    else if(results.some(x=>Array.isArray(x.result?.items)))answer+='\n\n这次检索没有匹配结果。没有补造来源；可以调整问题、扩大检索范围后再试。';
    if(receipts.length)answer+='\n\n已在本地模拟中完成目标位置写入：\n'+receipts.map(x=>'• '+x.destination).join('\n')+'\n\n本次没有另外生成文件。操作回执和工具调用记录已保留。';
